const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageOrientation } = require('docx');
const fs = require('fs');

// Brand colors
const NAVY = "0A1F44";
const GOLD = "B8945A";
const LIGHT_GOLD = "F5EFE3";
const DARK_TEXT = "1A1A1A";
const GREY_BORDER = "CCCCCC";

const border = { style: BorderStyle.SINGLE, size: 4, color: GREY_BORDER };
const borders = { top: border, bottom: border, left: border, right: border };

// Helper: section divider line
const divider = () => new Paragraph({
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 8 } },
  spacing: { before: 120, after: 240 },
  children: [new TextRun({ text: "" })]
});

// Helper: H1
const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 180 },
  children: [new TextRun({ text, bold: true, color: NAVY, size: 36, font: "Arial" })]
});

// Helper: H2 (phase header)
const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 320, after: 140 },
  children: [new TextRun({ text, bold: true, color: NAVY, size: 28, font: "Arial" })]
});

// Helper: H3 (subsection)
const h3 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_3,
  spacing: { before: 240, after: 100 },
  children: [new TextRun({ text, bold: true, color: GOLD, size: 24, font: "Arial" })]
});

// Helper: body paragraph
const body = (text, opts = {}) => new Paragraph({
  spacing: { after: 120 },
  children: [new TextRun({ text, size: 22, font: "Arial", color: DARK_TEXT, ...opts })]
});

// Helper: bullet
const bullet = (text, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  spacing: { after: 100 },
  children: [new TextRun({ text, size: 22, font: "Arial", color: DARK_TEXT })]
});

// Helper: bullet with bold lead-in
const bulletLead = (lead, rest, level = 0) => new Paragraph({
  numbering: { reference: "bullets", level },
  spacing: { after: 100 },
  children: [
    new TextRun({ text: lead, bold: true, size: 22, font: "Arial", color: NAVY }),
    new TextRun({ text: rest, size: 22, font: "Arial", color: DARK_TEXT })
  ]
});

// Helper: numbered step
const step = (text, level = 0) => new Paragraph({
  numbering: { reference: "numbers", level },
  spacing: { after: 100 },
  children: [new TextRun({ text, size: 22, font: "Arial", color: DARK_TEXT })]
});

// Helper: script line (italic, indented)
const scriptLine = (label, text) => new Paragraph({
  spacing: { after: 100 },
  indent: { left: 360 },
  children: [
    new TextRun({ text: label + " ", bold: true, size: 22, font: "Arial", color: GOLD }),
    new TextRun({ text: text, italics: true, size: 22, font: "Arial", color: DARK_TEXT })
  ]
});

// Helper: callout box
const callout = (title, lines) => {
  const children = [
    new Paragraph({
      spacing: { after: 80 },
      children: [new TextRun({ text: title, bold: true, size: 22, font: "Arial", color: NAVY })]
    })
  ];
  lines.forEach(line => {
    children.push(new Paragraph({
      spacing: { after: 60 },
      children: [new TextRun({ text: line, size: 22, font: "Arial", color: DARK_TEXT })]
    }));
  });

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: {
              top: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
              bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
              left: { style: BorderStyle.SINGLE, size: 16, color: GOLD },
              right: { style: BorderStyle.SINGLE, size: 4, color: GOLD }
            },
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
            margins: { top: 160, bottom: 160, left: 240, right: 240 },
            children: children
          })
        ]
      })
    ]
  });
};

// Cover title block
const coverTitle = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { before: 2400, after: 240 },
  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 28, font: "Arial", color: GOLD, characterSpacing: 80 })]
});

const coverHeadline = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 180 },
  children: [new TextRun({ text: "Sales Closer SOP", bold: true, size: 60, font: "Arial", color: NAVY })]
});

const coverSub = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 600 },
  children: [new TextRun({ text: "The Discovery to Close Framework", italics: true, size: 28, font: "Arial", color: DARK_TEXT })]
});

const coverBar = new Paragraph({
  alignment: AlignmentType.CENTER,
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 1 } },
  spacing: { after: 240 },
  children: [new TextRun({ text: "" })]
});

const coverDesc = new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 240 },
  indent: { left: 720, right: 720 },
  children: [new TextRun({
    text: "A repeatable, ethical, psychology-driven sales process for booking, qualifying, diagnosing, and closing independent med spa owners into the 90-Day Growth Engine.",
    size: 22, font: "Arial", color: DARK_TEXT, italics: true
  })]
});

// Build all content
const content = [
  coverTitle,
  coverHeadline,
  coverSub,
  coverBar,
  coverDesc,
  new Paragraph({ children: [new TextRun({ text: "" })], pageBreakBefore: true }),

  // ============ PURPOSE ============
  h1("Purpose of This SOP"),
  divider(),
  body("This document is the standard sales closer playbook for The Luxora Collective. It is built directly from a closed discovery call and codifies the exact structure, sequence, and language patterns that move a prospect from booked call to signed agreement."),
  body("Every phase below is non-negotiable. Skipping a phase breaks the psychology of the close. Run the call in order, every time."),

  callout("The Core Philosophy", [
    "1. We are not a marketing agency. We are aesthetic growth partners.",
    "2. Most med spas do not have a lead problem. They have a leak problem.",
    "3. The job of the closer is to diagnose first, prescribe second, and price last.",
    "4. We use ethical sales psychology. No used car tactics. No pressure."
  ]),

  // ============ CALL STRUCTURE OVERVIEW ============
  h1("Call Structure: The Six Phases"),
  divider(),
  body("Every discovery call follows six phases in this order. Total call time is 30 to 45 minutes."),
  bulletLead("Phase 1: ", "Rapport and Frame Setting (1 to 2 minutes)"),
  bulletLead("Phase 2: ", "Surface the Pain (2 to 3 minutes)"),
  bulletLead("Phase 3: ", "The Revenue Leak Audit (10 to 15 minutes)"),
  bulletLead("Phase 4: ", "Diagnosis and Recap (5 minutes)"),
  bulletLead("Phase 5: ", "Position the Solution (5 to 7 minutes)"),
  bulletLead("Phase 6: ", "Pricing, Close, and Next Step (3 to 5 minutes)"),

  // ============ PHASE 1 ============
  h2("Phase 1: Rapport and Frame Setting"),
  body("Goal: Make the prospect feel seen, lower their guard, and set the call structure so you stay in control without sounding scripted."),

  h3("Step 1: Personal connection"),
  body("Before anything business-related, find one personal hook. Their location, a recent post, a photo, the spa name, anything human. Name it specifically."),
  scriptLine("Example:", "Are you calling from Boca Raton? Oh, we just went down there about two months ago for my birthday. Loved it."),

  h3("Step 2: Set the frame"),
  body("This sentence is the frame. It tells the prospect what to expect, takes pressure off the close, and positions you as the one driving the call."),
  scriptLine("Use this:", "Here is how the call is going to go. I have already reviewed your spa. I am going to ask some deeper questions, understand what is going on, see where you get stuck, and walk you through exactly what that would look like. If we are a good fit, great. If not, I will point you in the right direction. Sound fair?"),

  callout("Why This Frame Works", [
    "It signals you have done your homework. Trust goes up.",
    "It removes the fear of being sold to. Defenses come down.",
    "It earns a yes early. The prospect is now bought into the process.",
    "It gives you permission to ask anything in the next 30 minutes."
  ]),

  // ============ PHASE 2 ============
  h2("Phase 2: Surface the Pain"),
  body("Goal: Get the prospect to articulate, in their own words, what is broken. You are not pitching. You are listening for the leak."),

  h3("The opening question"),
  scriptLine("Ask:", "What made you book a call today with us?"),
  body("Then shut up. Let them talk. Whatever they say first is the surface symptom. Whatever they say second or third is the real problem."),

  h3("The follow-up question"),
  scriptLine("Ask:", "Tell me a little bit about your practice right now."),
  body("Listen for these signals:"),
  bullet("Revenue range and growth direction"),
  bullet("What is working (leads, bookings, conversions)"),
  bullet("What is missing (retention, memberships, the back end)"),
  bullet("Life or business transitions (a move, new hire, new partner, lease ending)"),

  callout("Closer's Listening Rule", [
    "When a prospect says something is good but, that but is the close.",
    "Example: We make the money, but we want more. The pain is not revenue. It is systems.",
    "Mark the but. Come back to it in Phase 4 when you recap."
  ]),

  // ============ PHASE 3 ============
  h2("Phase 3: The Revenue Leak Audit"),
  body("Goal: Walk the prospect through a structured diagnostic that quantifies what they are losing. This is the heart of the call. The audit does the selling for you."),

  h3("The transition line"),
  scriptLine("Use this:", "It is not always a lead issue. It is a leak issue somewhere being disconnected. We have a really cool calculator we call our Revenue Leak Audit. It will take maybe five to ten minutes. Can I walk you through it?"),

  h3("Then share your screen"),
  body("Always share your screen during the audit. The visual builds authority and keeps the prospect engaged. Confirm they can see it before continuing."),

  h3("The audit categories (in order)"),
  body("Walk through every category. Do not skip. Every answer is data you will use in the diagnosis."),

  step("Practice basics: annual revenue, services offered, providers, total staff"),
  step("Lead flow: monthly inquiries, lead sources, ad spend, cost per lead, seasonality"),
  step("Speed to lead: response time, follow-up touches, automated vs manual"),
  step("Booking and no-shows: consult to book rate, deposit policy, no-show rate"),
  step("Consults: who runs them, scripted or freelanced, conversion rate, average first transaction"),
  step("Retention: memberships, packages, financing, loyalty programs"),
  step("Retail and reputation: skincare revenue percentage, Google review count and rating"),
  step("KPIs and tracking: lifetime value, first-year spend, provider performance, team incentives"),
  step("Devices: which lasers and devices, current utilization percentage"),
  step("Tech and partnerships: CRM and EMR in use, local partnerships and collaborations"),

  h3("Closer's job during the audit"),
  bulletLead("Acknowledge wins. ", "When something is strong, name it. You are rocking the consultations. Your no-show rate is excellent."),
  bulletLead("Flag leaks softly. ", "Do not lecture. Just note it. We usually see a minimum of 25% on memberships."),
  bulletLead("Plant the package seeds. ", "Drop concrete examples mid-audit so they imagine the upside. Mommy makeover package, summer ready package, wedding packages."),
  bulletLead("Tie wins to the brand. ", "This shows me you have excellent marketing and a really good social media presence. They are coming to you for a reason."),

  // ============ PHASE 4 ============
  h2("Phase 4: Diagnosis and Recap"),
  body("Goal: Show the prospect the audit score, the missing money, and the top three areas they are leaking from. This is where the deal is won or lost."),

  h3("Lead with the score and the number"),
  body("Open with the revenue health score and the estimated annual recovery dollar figure. The number is the anchor for everything that follows."),
  scriptLine("Use this:", "Your revenue health score is [X]. That is a little less than what we like to see. Estimated annual recovery is at least [$X]. That just means there is room for improvement."),

  h3("Walk through the top three leaks"),
  body("Pick the three most impactful leaks for this specific spa. For most med spas it is some combination of:"),
  bullet("Memberships (the number one missing piece in 90% of practices)"),
  bullet("Speed to lead and follow-up automation"),
  bullet("Monetizing and packaging (multi-treatment packages, themed bundles)"),
  bullet("Team and asset utilization (devices running below 100%, no partnerships)"),
  bullet("KPI tracking and lifetime value frameworks"),

  h3("The recap question"),
  body("After the recap, hand the call back to them. This is the test. If they self-identify the pain, you are 80% closed."),
  scriptLine("Ask:", "Did anything spark for you? Specifically, where do you think you need help the most?"),

  callout("Listen for the Self-Diagnosis", [
    "If they say retention, memberships, the back end, or systems, you are in.",
    "Confirm it back to them. I agree. That is exactly what we fix.",
    "Now they are not buying from you. They are agreeing with themselves."
  ]),

  // ============ PHASE 5 ============
  h2("Phase 5: Position the Solution"),
  body("Goal: Tell your story, frame the offer around their specific pain, and walk through the three pillars without overwhelming them."),

  h3("Step 1: Tell your story (60 to 90 seconds)"),
  body("Bethany's bio is the trust-builder. Use the bones of it but keep it conversational. Cover: years in the industry, operational and management background, what made you start consulting, why you built Luxora the way you did."),

  h3("Step 2: Position what Luxora is and is not"),
  scriptLine("Anchor:", "We are not a marketing agency. We are aesthetic growth partners."),
  body("Then explain why this matters. Most med spas do not need more leads. They need systems, operations, and structure."),

  h3("Step 3: Walk the three pillars"),

  body("Pillar one: Market Blueprint", { bold: true, color: NAVY }),
  bullet("Onboarding checklist sent immediately"),
  bullet("48-hour turnaround on extensive market research"),
  bullet("10 to 20 page deliverable covering area, industry, competition, and audit metrics"),
  bullet("No ads, no recommendations, no execution until we know exactly what they need"),

  body("Pillar two: Acquisition Engine", { bold: true, color: NAVY }),
  bullet("Full install of acquisition systems, not just an audit"),
  bullet("Free Luxora CRM (GHL-based) included, optional to use"),
  bullet("Ad management, AI follow-up, booking flow, front desk scripts"),
  bullet("Speed to lead audit and automation buildout"),

  body("Pillar three: Revenue Multiplier", { bold: true, color: NAVY }),
  bullet("Membership programs and tiered structures"),
  bullet("Package architecture (multi-treatment, themed, seasonal)"),
  bullet("Staff and sales training using ethical psychology, not used car tactics"),
  bullet("KPI checklist, lifetime value framework, laser ROI optimization"),
  bullet("Partnerships, referrals, reputation engine, retargeting campaigns"),

  h3("Step 4: The guarantee"),
  scriptLine("Say:", "We guarantee a minimum 2x return on your investment. New revenue or recovered revenue. We pride ourselves on under promising and over delivering."),

  h3("Step 5: The done-with-you frame"),
  body("This is the differentiator. Most agencies lock clients into long contracts. Luxora teaches and exits."),
  scriptLine("Say:", "This is done with you. We are not going to come in and do everything for you. We train you so you are not relying on us forever. After 90 days you should be ready to fly. We watch from the sidelines."),

  // ============ PHASE 6 ============
  h2("Phase 6: Pricing, Close, and Next Step"),
  body("Goal: Present price with confidence, handle the decision-maker question, and lock in a concrete next step before the call ends."),

  h3("The transition to pricing"),
  body("Wait for the prospect to ask. They almost always will. If they do not, prompt them after summarizing the fit."),
  scriptLine("Prompt:", "Based on everything I have shared, what are your thoughts about the program? Do you have any more questions for me?"),

  h3("Present the price (clean, no apology)"),
  scriptLine("Say:", "We are extremely competitive. The 90-Day Growth Engine is $9,000 total, which breaks down to $3,000 a month. That includes everything we just walked through."),

  body("Then add the partnership option:"),
  scriptLine("Say:", "After the 90 days, if you want continued ad management or hand-holding while memberships ramp up, our partnership program is $2,500 per month. Most people stay on for a while, but our goal is to launch you and let you run."),

  h3("Offer split payments"),
  scriptLine("Say:", "We offer split payments if that appeals to you more. We do not push the financing route because of interest, but it is available."),

  h3("Handle the decision-maker question"),
  body("If the prospect mentions a partner, sister, spouse, or CFO, do not push to close on this call. Lock in a follow-up call with the decision-maker on the calendar before you hang up."),
  scriptLine("Say:", "Absolutely. Let's get them on the schedule so they can hear the recap directly. What is their first name and email?"),

  callout("Critical Closing Moves", [
    "1. Always book the next call before ending the current one. Never leave it open-ended.",
    "2. Get the decision-maker's name and email on the call. Send the invite live with your assistant if possible.",
    "3. Pre-frame the next call: I will walk her through what we covered and answer her questions.",
    "4. Confirm timing in their timezone. Do not make them do the math."
  ]),

  h3("The final reinforcement (before goodbye)"),
  body("If the prospect drops a buying signal at the very end, reinforce it. Use their language."),
  scriptLine("Example reinforcement:", "Yes, we are huge on sales training. We teach ethical psychology, no used car tactics. We are A to Z. We are the company you were looking for."),

  // ============ OBJECTION PLAYBOOK ============
  h1("Objection Playbook"),
  divider(),
  body("Use these responses verbatim or close to it. They are tested and they work."),

  h3("Objection: I need to talk to my partner or sister."),
  scriptLine("Response:", "Absolutely. Let's get them on the schedule so they hear it directly. I want to make sure they have all the information. What is their email?"),
  body("Then book the call before ending this one."),

  h3("Objection: I am moving locations soon."),
  scriptLine("Response:", "The timing is actually perfect. After our 90 days together you will be ready to launch with a bang. New memberships, new packages, retargeting campaign to all your existing clients, an event to bring everyone in. We prep you to walk in the door already winning."),

  h3("Objection: I already have someone running my ads."),
  scriptLine("Response:", "Great. We can either take ads over completely or work alongside them. We will audit what they are doing and give them tips and tricks. We are happy either way. The ads are the smallest piece of what we do."),

  h3("Objection: How is this different from other companies I have seen?"),
  scriptLine("Response:", "Most agencies lock you into long contracts and keep you dependent. We do the opposite. We are done with you, not done for you. After 90 days you should not need us. We have had clients stay on, but it is their choice, not a contract."),

  h3("Objection: Pricing feels high."),
  scriptLine("Response:", "I hear you. Our guarantee is a minimum 2x return on your investment, in new or recovered revenue. We typically find $50,000 to $500,000 in missing money right out of the gate. The 90-day price is $9,000. Most clients recover that in the first 30 days from memberships and packages alone."),

  h3("Objection: Let me think about it."),
  body("Do not push. Book a follow-up. Always have a next step on the calendar."),
  scriptLine("Response:", "Of course. What questions can I answer right now while we are on? And what would you like to think through? Let's put a follow-up on the calendar so I can answer anything that comes up after."),

  // ============ POST-CALL ============
  h1("Post-Call Workflow"),
  divider(),

  h3("Within 15 minutes of the call ending"),
  step("Send the calendar invite to the decision-maker (if applicable). CC the prospect."),
  step("Send a short recap email or DM. Reference one specific thing they said. Attach the Revenue Leak Audit summary."),
  step("Log the call notes in the CRM: pain points, audit score, estimated recovery, objections, next step."),
  step("Tag the lead by stage: Booked Followup, Verbal Yes, Sent Agreement, Closed Won, Lost."),

  h3("Before the next call"),
  step("Re-read the notes. Re-watch the Fireflies recording if needed."),
  step("Prepare a custom open. Reference the new person by name and what their partner said about them."),
  step("Have the agreement and payment link ready to send live."),

  // ============ DO NOT DO LIST ============
  h1("The Do Not Do List"),
  divider(),
  body("These are immediate disqualifiers for any closer on the team."),
  bullet("Do not pitch before you diagnose. The audit comes first."),
  bullet("Do not skip the screen share during the audit."),
  bullet("Do not lead with price. Price comes after value."),
  bullet("Do not use pressure language, false scarcity, or urgency tactics."),
  bullet("Do not over-promise. We guarantee 2x. Do not promise 5x or 10x."),
  bullet("Do not let the call end without a concrete next step on the calendar."),
  bullet("Do not lecture the prospect on what they are doing wrong. Acknowledge wins first."),
  bullet("Do not bad-mouth other companies, agencies, or competitors."),

  // ============ FINAL ============
  h1("The Closer's Mantra"),
  divider(),
  callout("Read this before every call.", [
    "1. Diagnose before you prescribe.",
    "2. Listen for the but. The but is the close.",
    "3. Acknowledge wins before flagging leaks.",
    "4. Let the audit do the selling.",
    "5. Never leave a call without the next step locked in."
  ]),

  new Paragraph({
    spacing: { before: 480 },
    alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: "The Luxora Collective", bold: true, size: 22, font: "Arial", color: GOLD })]
  }),
  new Paragraph({
    alignment: AlignmentType.CENTER,
    children: [new TextRun({ text: "theluxoracollective.co", size: 20, font: "Arial", color: DARK_TEXT })]
  })
];

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: "Arial", color: NAVY },
        paragraph: { spacing: { before: 360, after: 180 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: NAVY },
        paragraph: { spacing: { before: 320, after: 140 }, outlineLevel: 1 } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Arial", color: GOLD },
        paragraph: { spacing: { before: 240, after: 100 }, outlineLevel: 2 } }
    ]
  },
  numbering: {
    config: [
      { reference: "bullets",
        levels: [
          { level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 720, hanging: 360 } } } },
          { level: 1, format: LevelFormat.BULLET, text: "◦", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 1440, hanging: 360 } } } }
        ] },
      { reference: "numbers",
        levels: [
          { level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
            style: { paragraph: { indent: { left: 720, hanging: 360 } } } }
        ] }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: content
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Luxora_Sales_Closer_SOP.docx", buffer);
  console.log("Done");
});

